def minimum_stone_total(piles, k):
    from heapq import heapify, heappop, heappush
    heap = [-pile for pile in piles]
    heapify(heap)
    for _ in range(k):
        pile = -heappop(heap)
        heappush(heap, -(pile - pile // 2))
    return -sum(heap)

